typedef struct OverworldWildBehaviorProfile {
    u8 chillState;
    u8 alertState;
    u8 alertEmote;
    u8 alertTime;
    u8 alertness;
    u8 attentiveState;
    u8 stamina;
    u8 tiredState;
    u8 restTime;
    u8 normalSpeed;
    u8 maxSpeed;
    u8 range;
    u8 jumpLevel;
    u8 profileId;
    u8 spawnState;
    u8 chillAction;
    u8 alertRange;
    u8 attentiveAction;
    u8 targetSelector;
    u8 movementStyle;
    u8 chillCooldown;
    u8 attentiveCooldown;
    u8 alertChance;
    u8 spawnDestination;
    u8 chillBattle;
    u8 alertBattle;
    u8 attentiveBattle;
    u8 tiredBattle;
} OverworldWildBehaviorProfile;

typedef struct OverworldWildBehaviorPrimitives {
    u8 spawnLocomotion;
    u8 chillLocomotion;
    u8 chillTarget;
    u8 alertLogic;
    u8 alertReaction;
    u8 attentiveLocomotion;
    u8 attentiveTarget;
    u8 activeReaction;
    u8 tiredReaction;
} OverworldWildBehaviorPrimitives;

typedef struct OverworldWildChillPrimitiveMap {
    u8 locomotion;
    u8 target;
} OverworldWildChillPrimitiveMap;

typedef struct OverworldWildAlertPrimitiveMap {
    u8 logic;
    u8 reaction;
} OverworldWildAlertPrimitiveMap;

typedef struct OverworldWildBehaviorContext {
    u16 species;
    u32 groupFlags;
    u8 level;
    u8 terrain;
    u8 shiny;
    u8 behaviorClass;
} OverworldWildBehaviorContext;

typedef struct OverworldWildBehaviorMatch {
    u16 species;
    u32 groupMask;
    u8 terrain;
    u8 minLevel;
    u8 maxLevel;
    u8 shiny;
    u8 behaviorClass;
} OverworldWildBehaviorMatch;

typedef struct OverworldWildBehaviorClassRule {
    OverworldWildBehaviorMatch match;
    u8 behaviorClass;
} OverworldWildBehaviorClassRule;

typedef struct OverworldWildBehaviorOverride {
    OverworldWildBehaviorMatch match;
    u32 mask;
    OverworldWildBehaviorProfile profile;
} OverworldWildBehaviorOverride;

typedef struct OverworldWildPlayfulTarget {
    int x;
    int y;
} OverworldWildPlayfulTarget;

